var throttledUpdateLegend = memoise(_throttledUpdateLegend);
function buildEcdf(values2, weights) {
  const sampleSize = Math.min(256, values2.length);
  const indices = Array.from({ length: sampleSize }, () => Math.floor(Math.random() * values2.length));
  const pairs = indices.map((i3) => [values2[i3], weights ? weights[i3] : 1]);
  pairs.sort((a2, b2) => a2[0] - b2[0]);
  const sortedValues = pairs.map(([v2]) => v2);
  const sortedWeights = pairs.map(([, w2]) => w2);
  let cumW = 0;
  const totalW = sortedWeights.reduce((s2, w2) => s2 + w2, 0);
  const quantiles = sortedWeights.map((w2) => {
    cumW += w2;
    return cumW / totalW;
  });
  const getQuantile2 = (target2) => {
    const idx = sortedValues.findIndex((v2) => v2 > target2);
    return idx === -1 ? 1 : quantiles[idx];
  };
  const getValueFromQuantile2 = (target2) => {
    const trimTarget = Math.min(Math.max(0.01, target2), 0.99);
    const idx = quantiles.findIndex((q2) => q2 > trimTarget);
    return idx === -1 ? sortedValues[sortedValues.length - 1] : sortedValues[idx];
  };
  return { getQuantile: getQuantile2, getValueFromQuantile: getValueFromQuantile2 };
}
